import {stepVehicle,roadCenter,angleDifference} from './physics.js';
import {CARS} from './catalog.js';
import {TRACK_RULES as TRACKS} from './race-settings.js';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export class RoomClient extends EventTarget{
 constructor(){super();this.socket=null;this.room=null;this.session=null;this.raceSeen=null;this.offset=0;this.rtt=0;this.seq=0;this.lastSent=0;this.controls={steer:0,throttle:false,brake:false,handbrake:false};this.history=new Map();this.predicted=null;this.visualError={x:0,s:0};this.manual=false;try{this.session=JSON.parse(sessionStorage.getItem('artvin-room-session'));}catch{};}
 emit(type,detail){this.dispatchEvent(new CustomEvent(type,{detail}));}
 serverNow(){return Date.now()+this.offset;}
 async connect(){if(this.socket?.readyState===WebSocket.OPEN)return;if(this.connecting)return this.connecting;this.manual=false;this.emit('connection','connecting');this.connecting=new Promise((resolve,reject)=>{const socket=this.socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws`);const timer=setTimeout(()=>{socket.close();reject(Error('Çevrimiçi sunucuya ulaşılamadı. Bağlantıyı kontrol edip tekrar dene.'));},8000);socket.onopen=()=>{clearTimeout(timer);this.connecting=null;this.emit('connection','connected');this.send({type:'ping',sentAt:Date.now()});clearInterval(this.pinger);this.pinger=setInterval(()=>this.send({type:'ping',sentAt:Date.now()}),2000);resolve();};socket.onerror=()=>{clearTimeout(timer);this.connecting=null;reject(Error('Oda sunucusuna bağlantı kurulamadı.'));};socket.onmessage=e=>{let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='pong'){const now=Date.now();this.rtt=Math.max(0,now-m.sentAt);const off=m.serverNow-(m.sentAt+now)/2;this.offset=this.hasClock?this.offset*.8+off*.2:off;this.hasClock=true;return;}if(m.type==='error'){this.pending?.reject(Error(m.message));this.pending=null;this.emit('error',m.message);return;}if(m.type==='welcome'){this.session={code:m.room.code,id:m.yourId,token:m.token||this.session?.token};this.publicOrigin=m.publicOrigin;if(!this.hasClock)this.offset=m.room.serverNow-Date.now();try{sessionStorage.setItem('artvin-room-session',JSON.stringify(this.session));}catch{}this.accept(m.room);this.pending?.resolve(m.room);this.pending=null;return;}if(m.type==='room')this.accept(m.room);};socket.onclose=()=>{clearTimeout(timer);clearInterval(this.pinger);this.connecting=null;this.pending?.reject(Error('Bağlantı kesildi. Yeniden bağlanmayı dene.'));this.pending=null;this.emit('connection',this.manual?'closed':'reconnecting');if(!this.manual&&this.session){clearTimeout(this.reconnector);this.reconnector=setTimeout(()=>this.resume().catch(()=>{}),1800);}};});return this.connecting;}
 send(m){if(this.socket?.readyState===WebSocket.OPEN)this.socket.send(JSON.stringify(m));}
 async request(message){await this.connect();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{if(this.pending){this.pending=null;reject(Error('Sunucudan yanıt alınamadı. Yeniden dene.'));}},9000);this.pending={resolve:v=>{clearTimeout(timer);resolve(v);},reject:e=>{clearTimeout(timer);reject(e);}};this.send(message);});}
 create(profile,track,hazardDensity){return this.request({type:'create',profile,track,hazardDensity});}
 join(code,profile){return this.request({type:'join',code:code.trim().toUpperCase(),profile});}
 resume(){if(!this.session)return Promise.reject(Error('Kayıtlı oda yok.'));return this.request({type:'resume',...this.session});}
 accept(room){this.room=room;const own=room.players.find(p=>p.id===this.session?.id);if(room.raceId&&room.raceId!==this.raceSeen){this.raceSeen=room.raceId;this.predicted=null;this.history.clear();this.seq=own?.seq||0;this.visualError={x:0,s:0};this.emit('race',room);}if(room.phase==='lobby'){this.raceSeen=null;this.predicted=null;this.history.clear();}
  for(const p of room.players){if(!p.v)continue;const list=this.history.get(p.id)||[];list.push({at:room.serverNow,v:{...p.v}});if(list.length>12)list.shift();this.history.set(p.id,list);}
  if(own?.v){const old=this.predicted?{x:this.predicted.x+this.visualError.x,s:this.predicted.s+this.visualError.s}:null;this.predicted={...own.v};if(own.finishTime===null&&!own.dnf&&room.phase==='racing'){const age=clamp((this.serverNow()-room.serverNow)/1000,0,.09),c=CARS[own.profile.car],t=TRACKS[room.track];if(age>0)stepVehicle(this.predicted,this.controls,age,{track:room.track,...t,power:c.speed,handling:c.grip,maxKmh:c.maxKmh,durability:c.durability,minS:-20});}if(old){this.visualError={x:clamp(old.x-this.predicted.x,-3,3),s:clamp(old.s-this.predicted.s,-8,8)};}}
  this.emit('room',room);
 }
 advance(dt,input){this.controls=input;const now=performance.now();if(now-this.lastSent>=33){this.lastSent=now;this.send({type:'input',seq:++this.seq,...input});}const own=this.room?.players.find(p=>p.id===this.session?.id);if(!this.predicted||!own)return null;const active=this.room.phase==='racing'||(this.room.phase==='countdown'&&this.serverNow()>=this.room.startAt);if(active&&own.finishTime===null&&!own.dnf){const c=CARS[own.profile.car];stepVehicle(this.predicted,input,dt,{track:this.room.track,...TRACKS[this.room.track],power:c.speed,handling:c.grip,maxKmh:c.maxKmh,durability:c.durability,minS:-20});}const decay=Math.exp(-dt*12);this.visualError.x*=decay;this.visualError.s*=decay;const v={...this.predicted,x:this.predicted.x+this.visualError.x,s:this.predicted.s+this.visualError.s};v.lateral=v.x-roadCenter(v.s,this.room.track);return v;}
 sample(id){const list=this.history.get(id);if(!list?.length)return null;const at=this.serverNow()-100;let a=list[0],b=list.at(-1);for(let i=1;i<list.length;i++)if(list[i].at>=at){a=list[i-1];b=list[i];break;}const t=clamp((at-a.at)/Math.max(1,b.at-a.at),0,1),v={...b.v};for(const key of ['s','x','speed','steering','lateralAccel','acceleration','slip'])v[key]=a.v[key]+(b.v[key]-a.v[key])*t;v.heading=a.v.heading+angleDifference(b.v.heading,a.v.heading)*t;v.lateral=v.x-roadCenter(v.s,this.room.track);return v;}
 configure(settings){this.send({type:'configure',settings});}
 updateProfile(profile){this.send({type:'profile',profile});}
 ready(value){this.send({type:'ready',value});}
 start(){this.send({type:'start'});}
 rematch(){this.send({type:'rematch'});}
 leave(){this.manual=true;this.send({type:'leave'});this.session=null;this.room=null;this.raceSeen=null;this.predicted=null;clearTimeout(this.reconnector);clearInterval(this.pinger);try{sessionStorage.removeItem('artvin-room-session');}catch{}this.socket?.close(1000);this.emit('left');}
 invite(){const origin=this.publicOrigin||location.origin;return this.room?origin+'/?oda='+encodeURIComponent(this.room.code):'';}
}
